window.ScripturaLexicons.BDAG_PART_0176 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-01\" data-source=\"BDAG\" data-search=\"ἱνατί advérbio interrogativo por quê?; por qual motivo? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱνατί</td><td>advérbio interrogativo</td><td>por quê?; por qual motivo?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-02\" data-source=\"BDAG\" data-search=\"ἰνδάλλομαι verbo médio formar ideias falsas; alimentar concepções estranhas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰνδάλλομαι</td><td>verbo médio</td><td>formar ideias falsas; alimentar concepções estranhas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-03\" data-source=\"BDAG\" data-search=\"Ἰόππη, ης, ἡ topônimo feminino Jope; porto da costa filisteia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰόππη, ης, ἡ</td><td>topônimo feminino</td><td>Jope; porto da costa filisteia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-04\" data-source=\"BDAG\" data-search=\"Ἰορδάνης, ου, ὁ hidrônimo masculino rio Jordão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰορδάνης, ου, ὁ</td><td>hidrônimo masculino</td><td>rio Jordão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-05\" data-source=\"BDAG\" data-search=\"ἰός, οῦ, ὁ substantivo masculino veneno; peçonha; ferrugem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰός, οῦ, ὁ</td><td>substantivo masculino</td><td>veneno; peçonha; ferrugem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-06\" data-source=\"BDAG\" data-search=\"Ἰουδαία, ας, ἡ topônimo feminino Judeia; território judeano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουδαία, ας, ἡ</td><td>topônimo feminino</td><td>Judeia; território judeano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-07\" data-source=\"BDAG\" data-search=\"ἰουδαί̈ζω verbo viver segundo costumes judaicos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἰουδαί̈ζω</td><td>verbo</td><td>viver segundo costumes judaicos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-08\" data-source=\"BDAG\" data-search=\"Ἰουδαϊκός, ή, όν adjetivo judeano; judaico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουδαϊκός, ή, όν</td><td>adjetivo</td><td>judeano; judaico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-09\" data-source=\"BDAG\" data-search=\"Ἰουδαϊκῶς advérbio à maneira judaica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουδαϊκῶς</td><td>advérbio</td><td>à maneira judaica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-10\" data-source=\"BDAG\" data-search=\"Ἰουδαῖος, αία, αῖον adjetivo; substantivo judeano; judeu; adepto da tradição mosaica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουδαῖος, αία, αῖον</td><td>adjetivo; substantivo</td><td>judeano; judeu; adepto da tradição mosaica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-11\" data-source=\"BDAG\" data-search=\"Ἰουδαϊσμός, οῦ, ὁ substantivo masculino judeanismo; judaísmo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουδαϊσμός, οῦ, ὁ</td><td>substantivo masculino</td><td>judeanismo; judaísmo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-12\" data-source=\"BDAG\" data-search=\"Ἰούδας, α, ὁ nome próprio masculino Judá; Judas, vários personagens BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰούδας, α, ὁ</td><td>nome próprio masculino</td><td>Judá; Judas, vários personagens</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-13\" data-source=\"BDAG\" data-search=\"Ἰουδίθ, ἡ nome próprio feminino Judite; nome feminino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουδίθ, ἡ</td><td>nome próprio feminino</td><td>Judite; nome feminino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-14\" data-source=\"BDAG\" data-search=\"Ἰουθίνη, ης nome próprio feminino Jutina; nome de criada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουθίνη, ης</td><td>nome próprio feminino</td><td>Jutina; nome de criada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-15\" data-source=\"BDAG\" data-search=\"Ἰουλία, ας, ἡ nome próprio feminino Júlia; nome feminino BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουλία, ας, ἡ</td><td>nome próprio feminino</td><td>Júlia; nome feminino</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-16\" data-source=\"BDAG\" data-search=\"Ἰούλιος, ου, ὁ nome próprio masculino Júlio; centurião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰούλιος, ου, ὁ</td><td>nome próprio masculino</td><td>Júlio; centurião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-17\" data-source=\"BDAG\" data-search=\"Ἰουνία, ας, ἡ nome próprio feminino Júnia; companheira de Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουνία, ας, ἡ</td><td>nome próprio feminino</td><td>Júnia; companheira de Paulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-18\" data-source=\"BDAG\" data-search=\"Ἰουνιᾶς, ᾶ, ὁ nome próprio masculino Júnias; variante onomástica discutida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰουνιᾶς, ᾶ, ὁ</td><td>nome próprio masculino</td><td>Júnias; variante onomástica discutida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-19\" data-source=\"BDAG\" data-search=\"Ἰοῦστος, ου, ὁ nome próprio masculino Justo; sobrenome BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἰοῦστος, ου, ὁ</td><td>nome próprio masculino</td><td>Justo; sobrenome</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0176-20\" data-source=\"BDAG\" data-search=\"ἱππεύς, έως, ὁ substantivo masculino cavaleiro; soldado de cavalaria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἱππεύς, έως, ὁ</td><td>substantivo masculino</td><td>cavaleiro; soldado de cavalaria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0176-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱνατί</h1><div class=\"entry-meta\"><span>advérbio interrogativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( frequentemente escrito separadamente; em <span class=\"greek\">ἱνα</span> <span class=\"greek\">τί</span> <span class=\"greek\">γένηται</span>; «com que finalidade?» B-D-F § 12, 3 ; W-Ver §5, 7e; Rob. 739 ) por quê?; por qual motivo? ( Aristoph ., Nub. 1192; Pla ., Apol. 14 p. 26d, Symp. 205a; Epict . 1, 29, 31; LXX ; PsSol 3:1 ; 4:1 ; TestAbr A 8 p. 85, 24 [Stone p. 18]; 86, 10f [St. p. 20]; TestJos 7:5 ; GrBar 1:2 ; Jos. , Bell. 6, 347 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:4</a> ; 27:46 ( Ps 21:2 ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:7</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:25</a> ( Ps 2:1 ); 7:26 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:29</a> ; 1 Cl 4:4 ( Gen 4:6 ); 35:7 ( Ps 49:16 ); 46:5, 7; B 3:1 ( Is 58:4 ). Com <span class=\"greek\">εἰς</span> <span class=\"greek\">τί</span> por quê e para quê? D 1:5 . B-D-F § 299, 4 .— M-M . sob o verbete <span class=\"greek\">ἵνα</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰνδάλλομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( relação etimológica com <span class=\"greek\">εἶδος</span>, <span class=\"greek\">οἶδα</span> ; Hom. e outros ; SibOr 13, 71) formar falsas ideias, alimentar concepções estranhas ( Dio Chrys . 11 [12], 53; Sext. Emp. , Adv. Math . 11, 122 <span class=\"greek\">ὁ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πλοῦτον</span> <span class=\"greek\">μέγιστον</span> <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">ἰνδαλλόμενος</span> ; Clem. Alex., Protr. 10, 103, 2) <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> a respeito de algo 1 Cl 23:2 (ver Harnack, Lghtf. , Knopf à passagem citada ).— DELG .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰόππη, ης, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Antig. Car. 151; Diod S 19, 59, 2; 19, 93, 7; Strabo 16, 2, 28; 34; Dionys. Perieg. in GGM II 160; OGI 602, 2; 1 Esdr 5:53 ; 1 Macc 10:75 al. ; 2 Macc 4:21 ; EpArist 115 ; Joseph .; SibOr 5, 251 . Sobre a grafia com um <span class=\"greek\">π</span> ou dois [assim em todos os manuscritos bíblicos] ver B-D-F § 40 ; W-Ver §5, 26, n. 54; Mlt-H. 102; Rob. 214 ; Schürer II 110f, 193 n. 35) Jope, atual Jafa, porto marítimo e cidade da costa filisteia a noroeste de Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:36</a>, 38, 42f ; 10:5, 8, 23, 32 ; 11:5, 13. —Schürer II 110–14 ( bibliografia ); FScholten, Palästina I: Jaffa ’31. BHHW II 803f.— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰορδάνης, ου, ὁ</h1><div class=\"entry-meta\"><span>hidrônimo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( י<span class=\"greek\">ַ</span>ר<span class=\"greek\">ְ</span>ד<span class=\"greek\">ֵּ</span>ן ) ( Strabo 16, 2, 16; Galen XI 693 K.; Tacitus, Hist. 5, 62; LXX , ParJer ; ApcSed 8:3 p. 133, 1 Ja.; EpArist , Philo , Joseph .; Just .; Mel. , Fgm. 8b, 42; SibOr 7, 67 [ <span class=\"greek\">Ἰόρδανος</span> , também encontrada em Joseph . e Paus . 5, 7, 4]; sobre o emprego do artigo com esse nome ver B-D-F § 261, 8 ) o Jordão, principal rio da Palestina ( EpArist 116 ). Nasce ao pé do monte Hermom, atravessa o mar da Galileia e deságua no mar Morto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:5f</a>, 13 ; 4:15 ( Is 8:23 ), 25 ; 19:1 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:5</a>, 9 ; 3:8 ; 10:1 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:3</a> ; 4:1 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:28</a> ; 3:26 ; 10:40 ; GEb 13, 74; PEg 2 66; HGuthe, RE XIV 573ff, Palästina 2 1927; Dalman , Orte 3 , índice; OWaser, V. Flussgott J.: AKaegi Festschr. 1919, 191–217; WvSoden, ZAW n.ver 16, ’39, 153f; NGlueck, The River Jordan 2 ’54.— TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Pind . et al. ; pap , LXX ; TestJob 43:8; TestReub 5:6 ; ApcMos 19)</p><p class=\"entry-text\">① veneno, peçonha</p><p class=\"entry-text\">ⓐ uso literal <span class=\"greek\">ἰὸν</span> <span class=\"greek\">ἐχίδνης</span> Papias ( 11:2 ) e <span class=\"greek\">ἰὸς</span> <span class=\"greek\">ἀσπίδων</span> ( TestJob 43:12; cf. Appian , Mithr. 88 §490 <span class=\"greek\">ἰὸς</span> <span class=\"greek\">ὄφεων</span> ; Philo , Leg. ad Gai. 166 ; Jos. , Bell. 1, 601 ; Constant. Manasses 4, 39 H. ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:13</a> ( Ps 13:3 ; 139:4 ). De origem animal (isto é, serpente; ver <span class=\"greek\">θηρίον</span> 1a <span class=\"greek\">β</span> ד ) também Hs 9, 26, 7 . Essas passagens, assim como Hv 3, 9, 7 e ITr 6:2 variante de leitura , mostram que a passagem ao emprego figurado foi natural.</p><p class=\"entry-text\">ⓑ uso figurado ( Aeschyl ., Eum. 730 al. ; Herm. Wr. p. 480, 15 Sc.; Test Reub 5:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:8</a>.</p><p class=\"entry-text\">② corrosão, ferrugem ( Theognis 451; Pla ., Tim. 59c, Rep. 10, 609a; Theocr . 16, 17 et al. ; SIG 2 587, 310 [329 b.c. ] <span class=\"greek\">σίδηρος</span> <span class=\"greek\">καταβεβρωμένος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰοῦ</span> ; SIG 284, 15; Herm. Wr. 14, 7; Ezk 24:6, 11f ; EpJer 10 e 23 ; Philo , Div. Rer. Her . 217 [<span class=\"greek\">χρυσὸς</span>] <span class=\"greek\">ἰὸν</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">παραδέχεται</span> , o ouro é elogiado por ser resistente à corrosão; semelhantemente Theognis 449–52; mas, se não for adequadamente refinado ou se sofrer contaminação química, alguns metais presentes num objeto de ouro ficarão sujeitos à oxidação) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:3</a> ; Dg 2:2 .— DELG <span class=\"greek\">ἰός</span> (3). M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουδαία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( י<span class=\"greek\">ְ</span>הו<span class=\"greek\">ּ</span>ד<span class=\"greek\">ָ</span>ה ; mas a palavra deve derivar do aramaico י<span class=\"greek\">ְ</span>הו<span class=\"greek\">ּ</span>ד<span class=\"greek\">ַ</span>י ; do adjetivo <span class=\"greek\">Ἰουδαῖος</span> com <span class=\"greek\">γῆ</span> ou <span class=\"greek\">χώρα</span> subentendido, como em Philo , Leg. ad Gai. 281 ) «Judeia» (desde Clearco, discípulo de Aristóteles: Fgm. 6 [em Jos. , C. Ap. 1, 179 ]; ins [Schürer II 1 n. 2]; PRyl 189, 5; LXX ; Philo ).</p><p class=\"entry-text\">① a parte meridional da Palestina, em contraste com Samaria, Galileia, Pereia e Idumeia: Judeia (ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:7f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:31</a> ; assim na LXX e frequentemente em Joseph ., Just . Também Strabo 16, 2, 34 com Galil. e Samar.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:1</a>, 5, 22 ; 3:1 ; 4:25 ; 24:16 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:7</a> ; 13:14 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:65</a> ; 2:4 ; 3:1 ; 5:17 ; 6:17 ; 21:21 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:3</a>, 47, 54 ; 7:1, 3 ; 11:7 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a> ; 8:1 ; 9:31 ; 12:19 ; 15:1 ; 21:10 ; 28:21 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:31</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:16</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:22</a> ; AcPl Ha 8, 29f=BMM verso 2. Metonimicamente, designando seus habitantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:5</a> ( <span class=\"greek\">Ἰ</span>. <span class=\"greek\">χώρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:5</a> ; ver <span class=\"greek\">Ἰουδαῖος</span> 1).— Buhl 64–75; HGuthe, RE IX 556–85; XXIII 713f ( bibliografia ); BHHW II 901; YAharoni, The Land of the Bible 2 ’79; MStern, em CRINT I/1, 308–76.</p><p class=\"entry-text\">② Judeia, entendida amplamente como a região habitada pelo povo de Israel: Judeia = «terra dos judeanos (judeus)», isto é, Palestina (Nicol. Dam. [I b.c. ]: 90 Fgm. 96 Jac. [em Jos. , Ant. 14, 9 ]; Diod S 40, 3, 2; Strabo 16, 2, 34; Memnon [I b.c. / I a.d. ]: 434 Fgm. 1, 18, 9 Jac. ; Ptolem . 5, 16, 1; cf. 15, 6–8 e Apotelesmatica 2, 3, 29 e 31. Cass. Dio 37, 16; 47, 28; Tacitus, Hist. 5, 9, 1; LXX ; EpArist 4 e12; Philo , Leg. ad Gai. 200 ; Joseph .; Just ., D . 32, 4.—Sobre o NT : ELevesque, Vivre et Penser 3, ’43/44, 104–11 nega o emprego em sentido mais amplo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:5</a> ; 4:44 ( variante de leitura <span class=\"greek\">Γαλιλαίας</span> , ver o verbete, ao final); 7:17 ; 23:5 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:37</a> ; 11:1, 29 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">χώρα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰ</span> . toda a região judeana (judaica) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:20</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅρια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">πέραν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰορδάνου</span> para o território judeano (judaico) além do Jordão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:1</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:1</a>. Sobre a menção da Judeia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:9</a> cf. as variantes e conjecturas em Nestle; EvDobschütz, ZWT 45, 1902, 407–10; Harnack, AG 1908, 65f; SKrauss, ZDPV 33, 1910, 225; OLagercrantz, Eranos 10, 1910, 58–60; LKöhler, ET 22, 1911, 230f. Também BZ 1, 1903, 219; 7, 1909, 219; 9, 1911, 218; ZNW 9, 1908, 253f; 255f; Haenchen à passagem citada ; TRE XXV 591–96.— OEANE III 253–57. M-M . EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἰουδαί̈ζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">viver submetido aos preceitos ou às tradições mosaicas; viver à maneira judeana ou judaica (assim em Plut ., Cic. 864 [7, 6]; Esth 8:17 ; Jos. , Bell. 2, 454 <span class=\"greek\">μέχρι</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">ἰ</span> .; ver também 463; Acta Pilati A 2, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a> ; BWander, Gottesfürchtige und Sympathisanten ( WUNT 104) ’98, 212–18; IMg 10:3 .— TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουδαϊκός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Artem . 4, 24 p. 217, 11; OGI 543, 16; 586, 7; Cleomedes [II a.d. ] in DDurham, The Vocabulary of Menander 1913, 27; 2 Macc 8:11 variante de leitura ; 13:21 ; EpArist 28 ; 121 ; Philo , In Flacc. 55 ; Jos. , Ant. 12, 34 ; 14, 228 ; 20 , 258 al. ; Just . A I, 53, 4 com <span class=\"greek\">Σαμαρειτικός</span> ) judeano (judaico) <span class=\"greek\">Ἰ</span>. <span class=\"greek\">μῦθοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:14</a>. <span class=\"greek\">Τὸ</span> <span class=\"greek\">Ἰ</span> . título de um evangelho judaico-cristão em alguns manuscritos (ver, por exemplo ASyn. 333, 51; também Hennecke-Schneemelcher [Wils.] I 136).— M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουδαϊκῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio ( Jos. , Bell. 6, 17 ) à maneira judeana (judaica), <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ζῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a>. — M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουδαῖος, αία, αῖον</h1><div class=\"entry-meta\"><span>adjetivo; substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Clearco, discípulo de Aristóteles, Fgm. 6 [em Jos. , C. Ap. 1, 179 ]; Theophr ., Fgm. 151 W. [WJaeger, Diokles v. Karystos ’38, 134–53: Theophrastus and the earliest Gk. report concerning the Judeans or Jews]; Hecataeus of Abdera [300 b.c. ] : 264 Fgm. 25, 28, 2a Jac. [em Diod S 1, 28, 2] al. ; Polyb .; Diod S ; Strabo ; Plut .; Epict . 1, 11, 12f, al. ; Appian , Syr. 50 §252f, Mithrid. 106 §498, Bell. Civ. 2, 90 §380; Artem . 4, 24 p. 217, 13; Diog. L. 1, 9; OGI 73, 4; 74, 3; 726, 8; CIG 3418; CB I/2, 538 no. 399b <span class=\"greek\">τ</span>. <span class=\"greek\">νόμον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Εἰουδέων</span> [sobre <span class=\"greek\">Ἰ</span> . em inscrições ver RKraemer, HTR 82, ’89, 35–53]; Mitt-Wilck. I/2, 55; 56 [ambos do séc. III a.C. ]; 57 [II b.c. ]; BGU 1079, 25 [41 a.d. ]; PFay 123, 16 [100 a.d. ]; POxy 1189, 9; LXX ; TestSol ; AscIs 2:7 ; EpArist ; SibOr ; Philo , Joseph ., Ar. , Just ., Tat . Para uma variedade de sinônimos ver Schürer III 87–91.). Em geral, como designação de ‘uma pessoa que se identifica com as crenças, os ritos e os costumes dos adeptos da tradição mosaica e profética de Israel’ (na Mishná, o termo-padrão é «israelita»). (Visto que o termo «judaísmo» sugere uma entidade monolítica que desconsidera as numerosas variedades de pensamento e manifestação social associadas a esses adeptos, o decalque ou empréstimo «judeano» é empregado aqui e em outros verbetes em que <span class=\"greek\">Ἰ</span> . é examinado. O problema semântico é agravado pela coexistência de pessoas que possuíam ascendência genealógica e daquelas que se tornaram prosélitas [sobre estas últimas cf. Cass. Dio 37, 17, 1; 67, 14, 2; 68, 1, 2]; e também de adeptos de Moisés que reconheciam Jesus como Messias [ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:13</a> no sentido 2d abaixo; ver também 2e <span class=\"greek\">α</span> ] e daqueles que não o reconheciam. Danos incalculáveis foram causados pela simples tradução de <span class=\"greek\">Ἰ</span> . por «judeu», pois muitos leitores ou ouvintes de traduções bíblicas não aplicam o discernimento histórico necessário para distinguir as circunstâncias e acontecimentos da Antiguidade das realidades étnicas, religiosas e sociais contemporâneas, o que faz com que os textos bíblicos alimentem desnecessariamente o antijudaísmo no sentido moderno da expressão.)</p><p class=\"entry-text\">① relativo a ser judeano (judeu), com ênfase na adesão à tradição mosaica: judeano, como verdadeiro adjetivo ( Philo , In Flacc. 29 ; Jos. , Ant. 10, 265 ) <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">Ἰ</span> . ( 1 Macc 2:23 ; 14:33 ) judeano <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:28</a> ; 22:3. <span class=\"greek\">ἄνθρωπος</span> 21:39. <span class=\"greek\">ἀρχιερεύς</span> 19:14. <span class=\"greek\">ψευδοπροφήτης</span> 13:6. <span class=\"greek\">ἐξορκισταί</span> 19:13. <span class=\"greek\">γυνή</span> ( Jos. , Ant. 11, 185 ) 16:1. <span class=\"greek\">χώρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:5</a>. —Entretanto <span class=\"greek\">γῆ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:22</a> deve ser entendido como referência à Judeia no sentido mais restrito (ver <span class=\"greek\">Ἰουδαία</span> 1), e designa a zona rural da Judeia, em contraste com a capital. A respeito de Drusila, descrita como <span class=\"greek\">οὔσα</span> <span class=\"greek\">Ἰουδαία</span> sendo judeana ou judia, mas, quanto à interpretação de que <span class=\"greek\">Ἰ</span> . aqui é um substantivo ver o sentido 2b.</p><p class=\"entry-text\">② pessoa judeana (judia), com ênfase na adesão à tradição mosaica: um judeano, <span class=\"greek\">Ἰουδαῖος</span> como substantivo (uso predominante ). Visto que Jerusalém estabelece o padrão de fidelidade à tradição de Israel e se situa na Judeia, <span class=\"greek\">Ἰ</span> . frequentemente sugere conformidade com as crenças e práticas ancestrais de Israel. Por sua vez, o nome geográfico forneceu aos não judeanos um termo aplicável a todos, inclusive aos seguidores de Jesus, que praticavam costumes diversamente associados à Judeia (observe-se a percepção romana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:15</a> [«judeanos» em Corinto]; 23:28 ).</p><p class=\"entry-text\">ⓐ (<span class=\"greek\">ὁ</span>) <span class=\"greek\">Ἰ</span> . judeano (quanto ao nascimento, à nacionalidade ou ao culto) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:25</a> ; ( Mitt-Wilck. I/2, 57, 5 [II b.c. ] <span class=\"greek\">παρ</span>’ <span class=\"greek\">Ἰουδαίου</span> =de um judeano) 4:9 ; 18:35 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:2</a>, 24 ; 19:34 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:16</a> ; 2:9f, 17, 28f (sobre o judeano «autêntico» cf. Epict . 2, 9, 20f <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄντι</span> <span class=\"greek\">Ἰουδαῖος</span> … <span class=\"greek\">λόγῳ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">Ἰουδαῖοι</span>, <span class=\"greek\">ἔργῳ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἄλλο</span> <span class=\"greek\">τι</span> ); 10:12 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:14</a> ; 3:28 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:11</a>. —singular coletivo ( Thu . 6, 78, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀθηναῖος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">Συρακόσιος</span> ; EpArist 13 <span class=\"greek\">ὁ</span> <span class=\"greek\">Πέρσης</span> ; B-D-F § 139 ; Rob. 408 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:1</a>.</p><p class=\"entry-text\">ⓑ sobre Drusila <span class=\"greek\">οὔσα</span> <span class=\"greek\">Ἰουδαία</span> sendo judeana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:24</a>, mas, quanto ao sentido simplesmente adjetival ver o final do sentido 1.</p><p class=\"entry-text\">ⓒ (<span class=\"greek\">οἱ</span>) <span class=\"greek\">Ἰουδαῖοι</span> (sobre o emprego do artigo B-D-F § 262, 1 ; 3 ) os judeanos <span class=\"greek\">οἱ</span> <span class=\"greek\">Φαρισαῖοι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:3</a> ; <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:13</a> ; cf. 5:1 ; 6:4 ; 7:2 ; <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . ( Appian , Mithrid. 117 §573 <span class=\"greek\">Ἰουδαίων</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">Ἀριστόβουλος</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:2</a> ; 27:11, 29 (nessas três últimas passagens , <span class=\"greek\">Ἰ</span> . é usado por não israelitas; o termo preferido de Mateus é <span class=\"greek\">Ἰσραήλ</span> ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:2</a> e frequentemente <span class=\"greek\">πόλις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:51</a> ; <span class=\"greek\">ἔθνος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:22</a> ; <span class=\"greek\">λαὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . 12:11. <span class=\"greek\">χώρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . 10:39 ( Just ., A I, 34, 2; cf. A I, 32, 4 <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">Ἰουδαίων</span> ). <span class=\"greek\">ἄρχων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:1</a> ; <span class=\"greek\">συναγωγὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:1a</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:6</a> ; 4:22 ; 18:20. <span class=\"greek\">Ἰ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἕλληνες</span> (sobre a combinação das duas palavras ver B-D-F § 444, 2 : com <span class=\"greek\">τε</span> … <span class=\"greek\">καί</span> ) judeanos e helenos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:1b</a> ; 18:4 ; 19:10 ; 20:21 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:24</a> ; 10:32 ; 12:13 ; PtK 2 p. 15, 7; <span class=\"greek\">ἔθνη</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἰ</span> .= não judeanos e judeanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:5</a> ; cf. ISm 1:2 . <span class=\"greek\">Ἰ</span>. <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προσήλυτοι</span> judeanos e prosélitos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:11</a> ; cf. 13:43 ; <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">Ἰ</span> . os judeanos que vivem entre as nações (na diáspora) 21:21. judeanos e não judeanos como perseguidores dos cristãos MPol 12:2 ; cf. também 13:1 ; 17:2 ; 18:1 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a> (Politeístas, judeus e cristãos Ar. 2, 1).— Dg 1 .—Sem o artigo ( cf. 19:3 <span class=\"greek\">φαρισαῖοι</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:15</a>, o que indica que nem todos os «judeanos» são visados, e sem referência a Israel, ou aos judeus, como entidade coletiva.</p><p class=\"entry-text\">ⓓ adepto da tradição mosaica que se identifica com Jesus Cristo judeano <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:13</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:20</a> e a subdivisão e <span class=\"greek\">α</span> abaixo. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:9</a> ; 3:9 ver Mussies 195.</p><p class=\"entry-text\">ⓔ em João, <span class=\"greek\">Ἰουδαῖοι</span> ou «judeanos» na maior parte das ocorrências (quanto às exceções ver a e c) constituem dois grupos <span class=\"greek\">α</span>. aqueles que, em graus diversos, se identificam com Jesus e seu ensino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:52</a> ; 10:19–21 ; 11:45 ; 12:11 al. <span class=\"greek\">β</span>. aqueles que se opõem a Jesus, com especial atenção à hostilidade oriunda das lideranças de Jerusalém, centro da fé e do culto israelitas; não há indícios de que João empregue o termo no sentido étnico geral sugerido pelo uso moderno da palavra «judeu», que abrange diversidades de crenças e práticas não contempladas pelos autores bíblicos, os quais tratam de diferenças e conflitos internos entre judeanos (israelitas): 1:19 ; 2:18, 20 ; 5:10, 15f ; 6:41, 52 (um debate); 7:1, 11, 13 ; 9:18, 22 ; 10:24, 31, 33 (em contraste com os <span class=\"greek\">πολλοί</span> vindos de «além do Jordão», 10:40–42 , que certamente são israelitas) 11:8 ; 13:33 ; 18:14. Ver Hdb. exc. sobre Jo 1:19 e, de outro ponto de vista, JBelser, TQ 84, 1902, 265ff; WLütgert, Heinrici Festschr. 1914, 147ff, Schlatter Festschr. 1922, 137–48; GBoccaccini, Multiple Judaisms: BRev XI/1 ’95, 38–41, 46.— <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:20</a> afirma que Jesus não se envolveu em atividade sectária. Sobre o sentimento antijudeano no Evangelho de João, ver ainda, ver EGraesser, NTS 11, ’64, 74–90; DHare, RSR , July, ’76, 15–22 ( lit. ); Hdb. exc. sobre Jo 1:19 ; BHHW II 906–11, 901f, 905.—LFeldman, Jew and Gentile in the Ancient World ’93.—MLowe, Who Were the <span class=\"greek\">Ἰουδαῖοι</span> ?: NovT 18, ’76, 101–30; idem <span class=\"greek\">Ἰουδαῖοι</span> of the Apocrypha [ NT ]: NovT 23, ’81, 56–90; UvonWahlde, The Johannine ‘Jews’—A Critical Survey: NTS 28, ’82, 33–60; JAshton, ibid. 27, ’85, 40–75 (J).—Sobre a repercussão de <span class=\"greek\">Ἰουδαῖοι</span> entre os gentios ver ESmallwood, The Jews under Roman Rule de Pompey to Diocletian ’81; SCohen, Crossing the Boundary and Becoming a Jew: HTR 82, ’89, 13–33; PvanderHorst, NedTTs 43, ’89, 106–21 (c. 200 a.d. ); PSchäfer, Judeophobia, Attitudes toward the Jews in the Ancient World ’97.—Sobre o vocábulo em seu conjunto ver <span class=\"greek\">Ἱσραήλ</span> end. Sobre <span class=\"greek\">Ἰουδαῖοι</span> em inscrições ver SEG XXXIX, 1839. M-M . EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουδαϊσμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">judeanismo/judaísmo = o modo judeano de crença e de vida ( 2 Macc 2:21 ; 8:1 ; 14:38 ; 4 Macc 4:26 ; inscrição sinagogal de Estobi, linha 8: ZNW 32, ’33, 93f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:13f</a>. Em contraste com <span class=\"greek\">Χριστιανισμός</span> IMg 10:3 ; IPhld 6:1 . <span class=\"greek\">κατὰ</span> ( <span class=\"greek\">νόμον</span> é provavelmente uma glosa) <span class=\"greek\">Ἰουδαϊσμὸν</span> <span class=\"greek\">ζῆν</span> viver conforme o modo de vida judeano (judaísmo) IMg 8:1 .— TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰούδας, α, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( י<span class=\"greek\">ְ</span>הו<span class=\"greek\">ּ</span>ד<span class=\"greek\">ָ</span>ה Judá, de etimologia desconhecida; LXX ; TestSol 1:12 D ; Test12Patr ; JosAs 27:6; AscIs , EpArist , Philo , Joseph ., Just ., Mel. , P. 93, 703.—A forma indeclinável <span class=\"greek\">Ἰουδά</span> , que ocorre ocasionalmente na LXX [ por exemplo Gen 29:35 ; 2 Macc 14:13 Swete ; Thackeray 163] não deve ser pressuposta para nossa literatura , nem mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:39</a> ) Judas, Judá (em hebraico, grafia inglesa convencional para os sentidos 1 e 2), Judas ( em grego, grafia convencional para os sentidos 3–7), Judas (ver o sentido 8 abaixo); cf. B-D-F § 53, 1 ; 55, 1 a; Mlt- H , 143f.</p><p class=\"entry-text\">① Judá, filho do patriarca Jacó</p><p class=\"entry-text\">ⓐ referindo-se à pessoa : na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:2f</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:33</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰούδαν</span> por intermédio de Judá 1 Cl 32:2 .</p><p class=\"entry-text\">ⓑ a tribo de Judá ( Judg 1:2 ) <span class=\"greek\">ἐξ</span> <span class=\"greek\">Ἰούδα</span> <span class=\"greek\">ἀνατέταλκεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:14</a>. Também <span class=\"greek\">φυλὴ</span> <span class=\"greek\">Ἰούδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:5</a> ; 7:5 ( Just ., D . 43, 1).</p><p class=\"entry-text\">ⓒ o território pertencente à tribo de Judá ( Josh 11:21 ; 2 Ch 28:18 ) <span class=\"greek\">Βηθλέεμ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">Ἰούδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6a</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:4</a> D ; <span class=\"greek\">ἡγεμόνες</span> <span class=\"greek\">Ἰ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6b</a> ; <span class=\"greek\">πόλις</span> <span class=\"greek\">Ἰ</span> . ( 2 Ch 23:2 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:39</a> ( cf. CTorrey, HTR 17, 1924, 83–91). <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰ</span> . (com <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰσραήλ</span> ) os habitantes da terra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> ( Jer 38:31 ).</p><p class=\"entry-text\">② Judá, pessoa na genealogia de Jesus</p><p class=\"entry-text\">ⓐ <span class=\"greek\">Ἰ</span> . filho de <span class=\"greek\">Ἰωσήφ</span> 2: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:30</a>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">Ἰ</span> . filho de <span class=\"greek\">Ἰωανάν</span> : <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:26</a> variante de leitura</p><p class=\"entry-text\">③ Judas, chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">Γαλιλαῖος</span> , um revolucionário da época de Quirino, «nos dias do recenseamento» ( cf. Jos. , Ant. 18, 4 –10, 23–25; 20, 102, Bell. 2, 118 ; 433 ; 7, 253 .—Schürer I 381f; 414; 417f; 425; II 599–606) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:37</a>. —WLodder, J. de Galileër: NTS 9, 1926, 3–15.</p><p class=\"entry-text\">④ Judas de Damasco, que hospedou Paulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:11</a>.</p><p class=\"entry-text\">⑤ Judas, apóstolo, chamado <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Ἰακώβου</span> filho de Jacó ou Tiago (linguisticamente, <span class=\"greek\">ἀδελφός</span> também poderia ser subentendido: Alciphron 4, 17, 10 <span class=\"greek\">Τιμοκράτης</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Μητροδώρου</span> , isto é, seu irmão), para distingui-lo daquele que denunciou Jesus. Ele aparece nas listas de apóstolos somente nos escritos de Lucas, nos quais são mencionados especificamente dois homens chamados Judas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:16</a> e pressupostos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:13</a> ; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:22</a>.</p><p class=\"entry-text\">⑥ Judas, diversas vezes chamado <span class=\"greek\">Ἰσκαριώθ</span> ou (<span class=\"greek\">ὁ</span>) <span class=\"greek\">Ἰσκαριώτης</span> ( ver verbete ), aquele que entregou Jesus às autoridades <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:4</a> ; 26:14, 25, 47 ; 27:3 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:19</a> ; 14:10, 43 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:16</a> ( <span class=\"greek\">προδότης</span> ‘traidor’); 22:3, 47f ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:4</a> ; 13:29 ; 18:2f, 5 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>, 25 ; GEb 34, 61; Agr 23b; MPol 6:2 (também Mel. , P. 93, 703). Seu pai era Simão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:2</a>, e esse Simão também é chamado <span class=\"greek\">Ἰσκαριώτης</span> 6:71 ; 13:26 ( variante de leitura o descrevia como <span class=\"greek\">Ἰσκαρ</span> .). Sobre o próprio Judas e as tradições a seu respeito, inclusive o modo de sua morte, ver Papias ( 1:5 Lat. [ cf. Hippolytus in Da 60 p. 338, 3 Bonwetsch]; 3:1, 2).—Cf. EPreuschen, Antileg. 2 1905, 98. Bibliografia em Hennecke-Schneemelcher (Wils.) II 62–64 (ver também I 313f) bem como GMarquardt, D. Verrat des J. Isch.—eine Sage 1900; WWrede, Vorträge u. Studien 1907, 127–46; FFeigel, D. Einfluss d. Weissagungsbeweises 1910, 48ff; 95; 114; WSmith, Ecce Deus 1911, 295–309; KWeidel, StKr 85, 1912, 167–286; GSchläger, Die Ungeschichtlichkeit des Verräters J.: ZNW 15, 1914, 50–59; MPlath, ibid. 17, 1916, 178–88; WCadman, The Last Journey of Jesus to Jerus. 1923, 129–36; JRobertson, Jesus and J. 1927; DHaugg, J. Isk. in den ntl. Berichten 1930 ( lit. ); JFinegan, D. Überl. d. Leidens-u. Auferstehungsgesch. Jesu ’34; FDanker, The Literary Unity of <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:1</a>–25 : JBL 85, ’66, 467–72. Especialmente sobre a morte de Judas: RHarris, AJT 4, 1900, 490–513; JBernard, Exp. 6th ser. , 9, 1904, 422–30; KLake, Beginn. V ’33, note 4, 22–30; PBenoit, La mort de Judas, AWikenhauser Festschr. ’53, 1–19; KLüthi, Judas Iskarioth in d. Geschichte d. Auslegung von d. Reformation bis zur Gegenwart ’55; idem , D. Problem d. Judas Iskarioth neu untersucht: EvTh 16, ’56, 98–114; MEnslin, How the Story Grew: Judas in Fact and Fiction: FGingrich Festschr. , ed. Barth and Cocroft, ’72, 123–41; e ver <span class=\"greek\">παραδίδωμι</span> e <span class=\"greek\">πρηνής</span> .—JBrownson, Neutralizing the Intimate Enemy—The Portrayal of Judas in the Fourth Gospel: SPSBL ’92, 49–60; WKlassen, Judas—Betrayer or Friend of Jesus? ’96; ver também WVogler, Judas Iskarioth ’83.</p><p class=\"entry-text\">⑦ Judas, chamado <span class=\"greek\">Βαρσαββᾶς</span> (ver o verbete), profeta cristão em posição de liderança na comunidade de Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:22</a>, 27, 32. Seu nome também aparece no versículo interpolado 34.</p><p class=\"entry-text\">⑧ Judas, irmão de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:55</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:3</a>. Provavelmente se trata do mesmo homem chamado Judas em Jd 1. — M-M . EDNT .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουδίθ, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">indeclinável ( י<span class=\"greek\">ְ</span>הו<span class=\"greek\">ּ</span>ד<span class=\"greek\">ִ</span>ית ) Judite</p><p class=\"entry-text\">① uma heroína israelita ( Jdth 8–16 ) 1 Cl 55:4 .</p><p class=\"entry-text\">② uma criada de Ana GJs 2:2 variante de leitura ; 2:3 variante de leitura</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουθίνη, ης</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(uma formação nominal incomum, transmitida também como <span class=\"greek\">Εὐθίνη</span> ; cf. <span class=\"greek\">Εὐθήνη</span> provavelmente PLond 261, 178 col. 12 p. 58 [I a.d. ]; ver deStrycker p. 313ff) Jutina nome da criada de Ana GJs 2:2f ( variante de leitura <span class=\"greek\">Ἰουδίθ</span> ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουλία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Júlia, nome comum</p><p class=\"entry-text\">① destinatária de uma saudação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:15</a> ( <span class=\"greek\">Ἀουλία</span> P 46 ). O nome se encontra até entre mulheres escravizadas na casa imperial. GMilligan, The NT Documents 1913, 183.</p><p class=\"entry-text\">② O nome <span class=\"greek\">Ἰ</span> . aparece também como variante de leitura no versículo 7 (em lugar de <span class=\"greek\">Ιουνιαν</span> ; ver <span class=\"greek\">Ἰουνιᾶς</span> e <span class=\"greek\">Ἰουνία</span> ).— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰούλιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Júlio, nome comum (também em Josefo .), usado por um centurião da coorte imperial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:1</a>, 3 ( variante de leitura <span class=\"greek\">Ἰουλιανός</span> , também nome de um <span class=\"greek\">ἑκατοντάρχης</span> Jos. , Bell. 6, 81 ).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουνία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( SEG XVIII, 143 [c. 43 a.d. ]; sobre a forma ver Mlt-H. 155) Júnia, compatriota ou parente de Paulo, pessoa que, como Paulo, sofreu prisão e era notável entre os apóstolos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:7</a> variante de leitura Comentadores antigos consideravam Andrônico e Júnia um casal. Algumas identificações patrísticas (JFitzmyer, Anchor Bible: Romans, ’93, 737f) favorecem essa leitura de seu nome no texto (assim NRSV , REB ; RCervin, NTS 40, ’94, 464–70); em oposição a essa identificação Ltzm. ( Hdb. ad loc. ), que não apresenta provas para sustentar sua afirmação de que o contexto parece excluí-la. Além disso, ao contrário de <span class=\"greek\">Ἰουνιᾶν</span> (ver o verbete seguinte), a forma <span class=\"greek\">Ἰουνίαν</span> é efetivamente atestada com essa acentuação em alguns manuscritos (ver N., aparato crítico ). Sobre o prestígio apostólico conferido a uma mulher ver Aa I, 235 app. ln. 2: <span class=\"greek\">ἰσαπόστολος</span> de Tecla.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰουνιᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Júnias (não atestado em outras fontes; poderia ser uma forma abreviada do nome comum Juniano; ver B-D-F § 125, 2 ; Rob. 172 ) segundo a leitura do texto de Nestle um cristão judeano que esteve preso com Paulo ou viveu experiência semelhante <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:7</a> ; ver <span class=\"greek\">Ἀνδρόνικος</span> . Entretanto, a forma acentuada <span class=\"greek\">Ἰουνιᾶν</span> não tem, como tal, apoio na tradição manuscrita; para uma crítica de B-D-R §125, 2, 6 em relação à leitura de Nestle ver UPlisch, NTS 42, ’96, 477f, n. 2. Sobre a grande probabilidade de que se trate de uma mulher chamada Júnia ver o verbete anterior.— M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἰοῦστος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( <span class=\"greek\">Κυπρ</span> . I p. 42 no. 27 nome do <span class=\"greek\">ἀρχιερεὺς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νήσου</span> [Chipre]; PWarr 16, 4 [III a.d. ]), nome frequentemente usado por judeanos e prosélitos (ver Lghtf. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:11</a> ) Justo, sobrenome</p><p class=\"entry-text\">① de José Barsabás, um dos dois candidatos à escolha de um apóstolo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:23</a> ; Papias ( 2:9 ; 11:2 ).</p><p class=\"entry-text\">② de Tício, prosélito coríntio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:7</a>. ver Goodsp. sob o verbete <span class=\"greek\">Τίτιος</span> .</p><p class=\"entry-text\">③ de um cristão judeu chamado Jesus, que apoiou Paulo, então prisioneiro, em seu trabalho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:11</a>. Deissmann sobre <span class=\"greek\">Ἰησοῦς</span> 5.—Sobre o nome duplo ver Dssm. , B 183f ( BS 315f).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0176-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἱππεύς, έως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver os dois verbetes seguintes; Hom . et al. ; ins , pap , LXX , Philo ; Jos. , Vi. 157 al. ; SibOr 3:612805 ; ) acusativo plural <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἱππεῖς</span> (Polyaenus 1, 29, 1; 8, 23, 12; SIG 502, 9 [228/225 b.c. ]; 627, 15 [183 b.c. ]) cavaleiro, soldado de cavalaria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:23</a>, 32 ; MPol 7:1 .— DELG sob o verbete <span class=\"greek\">ἵππος</span> . M-M .</p></section></article>\n"};
